sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var citySysID = g_form.getValue('city');
    var stateSysID = g_form.getValue('state');
    var baseUtils = new GlideAjax('x_1593193_bases.BaseUtils');
    baseUtils.addParam('sysparm_name', 'cityStateValidation');
    baseUtils.addParam('sysparm_baseCity', citySysID);
    baseUtils.addParam('sysparm_baseState', stateSysID);

    baseUtils.getXMLAnswer(function(response) {
        if (response == 'true') {
            g_form.addErrorMessage('The city is already registered');
            g_form.setValue('city', '');
            g_form.setValue('state', '');
        } else {
            g_form.clearMessages();
        }
    });

}
